-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.hunter.ranged.Name"] = "Fernkampf"
L["rm.era.hunter.ranged.Description"] = "Jeder Jäger von Stufe 1 bis 60, alle Talentbäume. Ziehen mit Mal des Jägers, Gezieltem Schuss und Automatischem Schuss. Solo tankt der Begleiter: Ihr eigener Schlangenbiss, dann Gezielter Schuss, Arkaner Schuss und Mehrfachschuss nur, solange Ihr Mana über der Hälfte liegt, Erschütternder Schuss zum Kiten, bevor Sie einen Begleiter haben. In einer Gruppe Gezielter Schuss und Mehrfachschuss direkt nach einem Automatischen Schuss, damit dieser nie verzögert wird, Schlangenbiss außerhalb von Schlachtzügen, Arkaner Schuss nur vor Gezieltem Schuss oder auf ein sterbendes Ziel. Nahkampftasten, wenn ein Gegner zu nah ist, Spontanzauber in Bewegung, Mehrfachschuss und Salve gegen drei oder mehr Gegner. Erinnerungen: Falke (davor Affe), Aura des Volltreffers, Begleiterpflege, Schnellfeuer, Zorn des Wildtiers und Volksfähigkeiten gegen Elitegegner und in Instanzen, Einschüchterung und Totstellen. Fallen, Zurechtstutzen, Tier füttern, Einlullender Schuss und Positionierung bleiben Ihnen überlassen."
L["rm.era.hunter.ranged.icyveins.Name"] = "Fernkampf, mit Clipping (Icy Veins)"
L["rm.era.hunter.ranged.icyveins.Description"] = "Standardmäßig deaktiviert; aktivieren Sie sie für eine Fernkampfwaffe, die schneller als 3,0 Sekunden ist. Wie Jäger: Fernkampf, aber in einer Gruppe kommen Gezielter Schuss und Mehrfachschuss, sobald sie bereit sind, selbst wenn das einen Automatischen Schuss verzögert, Schlangenbiss wird nie genutzt, und Schnellfeuer, Zorn des Wildtiers und Volksfähigkeiten werden bei jedem Pull genutzt."
L["rm.era.hunter.ranged.simulator.Name"] = "Fernkampf, Schlangenbiss im Schlachtzug (Simulation)"
L["rm.era.hunter.ranged.simulator.Description"] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn der Schlachtzug Platz für Ihren Biss als Schwächungszauber hat. Wie Jäger: Fernkampf, aber in einer Gruppe wird Schlangenbiss überall aufrechterhalten, auch in Schlachtzügen, unter 5 Sekunden erneuert, während Gezielter Schuss und Mehrfachschuss beide abklingen, und Arkaner Schuss wird nie genutzt."
L["rm.forever.hunter.ranged.Name"] = "Fernkampf (Wowhead)"
L["rm.forever.hunter.ranged.Description"] = "Jeder Fernkampfjäger von Stufe 1 bis 60 (Tierherrschaft, Treffsicherheit und Überleben bis Streichertritt) und der Forever-Jäger-Standard. Pull: Mal des Jägers, Heckenschützenschuss, solange Schneller Tod anhält, Automatischer Schuss. Dann Ihr eigener Schlangenbiss, zweimal Falke beschwören und einmal Arkaner Schuss auf ihrer gemeinsamen Abklingzeit (Arkaner Schuss bei Abklingzeit-Ende vor Falke beschwören), Heckenschützenschuss unter Schneller Tod oder gegen Elitegegner, Gezielter Schuss. Zwei oder mehr Gegner kämpfen gegen Sie: Mehrfachschuss statt Gezieltem Schuss, Sprengfalle bei drei Gegnern in Ihrer Nähe, Salve bei fünf. In Bewegung: nur Spontanschüsse. Ein Gegner in Nahkampfreichweite erhält Raptorstoß und Mungobiss. Erinnerungen: Aspekt des Falken (davor Aspekt des Affen), Aura des Volltreffers, Begleiter rufen und wiederbeleben, Schnellfeuer, Zorn des Wildtiers und Kochendes Blut gegen Elitegegner oder in Dungeons, Einschüchterung, wenn ein Gegner Sie angreift. Begleiterbefehle, Füttern, Kiten und Totstellen bleiben Ihnen überlassen; deaktivieren Sie die Begleiter-Erinnerungen, wenn Sie Einsamer Wolf spielen. Sie liest nie Ihr Mana oder die Gesundheit anderer, die Forever vor Addons verbirgt, daher kommen Mal des Jägers und Schlangenbiss auf jedes Ziel, und Tier heilen bleibt Ihnen überlassen."
L["rm.forever.hunter.ranged.mobalytics.Name"] = "Fernkampf, manasparend (Mobalytics)"
L["rm.forever.hunter.ranged.mobalytics.Description"] = "Manasparender Levelstil von Mobalytics, eine Alternative zur empfohlenen integrierten Fernkampfrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Hält Ihren Schlangenbiss aufrecht, einen beschworenen Falken draußen, Gezielter Schuss (Mehrfachschuss gegen zwei oder mehr Gegner) und nie Arkaner Schuss, sobald Falke beschwören bekannt ist; der zweite Falke auf ein gesundes Ziel entfällt, da Forever die Gesundheit des Ziels verbirgt. Derselbe Pull, Nahkampf, dieselbe Bewegung und dieselben Erinnerungen wie die integrierte Rotation nach Wowhead."
L["rm.forever.hunter.survival.Name"] = "Überleben im Nahkampf (Wowhead)"
L["rm.forever.hunter.survival.Description"] = "Überleben im Nahkampf mit zwei Waffen, sobald Überleben Ihr Haupttalentbaum mit 21 Punkten ist, die Stufe von Streichertritt (bis dahin levelt Sie die integrierte Fernkampfrotation, wie die Leitfäden raten). Pull mit Mal des Jägers und Schlangenbiss, dann Mungobiss, Streichertritt, Raptorstoß und Gegenangriff, mit Sprengfalle gegen drei oder mehr Gegner. Außerhalb des Nahkampfs schießt sie: Schlangenbiss, Arkaner Schuss, Gezielter Schuss, Automatischer Schuss. Erinnerungen: Aspekt des Wildtiers, Mal des Jägers (Beute aufspüren benötigt es), Schnellfeuer und Kochendes Blut gegen Elitegegner oder in Dungeons, Abschreckung, solange Sie die Aufmerksamkeit des Ziels halten, Begleiterpflege (Gesundheit ist unter Forever verborgen, daher bleibt Tier heilen Ihnen überlassen). Ein optionaler Schritt mit Feuerbrandfalle ist standardmäßig deaktiviert."
L["rm.forever.hunter.survival.weave.Name"] = "Überleben, Zweihand-Weaving (Wowhead)"
L["rm.forever.hunter.survival.weave.Description"] = "Rein-und-raus-Weaving nach Wowhead für einen Überlebensjäger mit Zweihandwaffe, eine Alternative zur empfohlenen integrierten Nahkampfrotation für Überleben, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Im Nahkampf: Mungobiss und Raptorstoß; wenn Raptorstoß noch mehr als 2,5 Sekunden entfernt ist, Streichertritt und heraustreten. Außerhalb des Nahkampfs: Schlangenbiss, Arkaner Schuss, Gezielter Schuss und Automatischer Schuss, bis Raptorstoß fast bereit ist, dann wieder hinein. Die Bewegung übernehmen Sie; RM folgt Ihrer Entfernung."
L["rm.mop.hunter.beastmastery.Name"] = "Empfohlen"
L["rm.mop.hunter.beastmastery.Description"] = "Automatisch gewählt in der Spezialisierung Tierherrschaft. Eröffnet mit Mal des Jägers und Fass!, dann: Tödlicher Schuss, Fass! (kurz zurückgehalten, wenn Zorn des Wildtiers gleich bereit ist), Die Vögel, Luchsansturm, Alphatier und Ihr Schuss aus der Talentstufe 6, wenn gewählt, Feuer konzentrieren bei fünf Stapeln Raserei (oder vier, die bald auslaufen), aber nicht während Zorn des Wildtiers, Schlangengift auf Zielen, die lange genug leben, Kobraschuss, um es zu erneuern, Arkaner Schuss bei 80 Fokus oder während Zorn des Wildtiers, dann Kobraschuss (Zuverlässiger Schuss vor Stufe 81). Wenn zwei oder mehr Gegner gegen Sie kämpfen, hält sie Raubtierhiebe mit Mehrfachschuss aufrecht, spart Fass! bei großen Gruppen für überschüssigen Fokus auf und schlägt ab drei Gegnern Sprengfalle vor. Erinnerungen: Begleiter herbeigerufen, wiederbelebt und geheilt, Aspekt des Falken oder des eisernen Falken, Gegenschuss, Eifer sowie Zorn des Wildtiers, Schnellfeuer, Stampede und Volksfähigkeiten, wenn sich der Kampf lohnt (ein Elitegegner, ein Dungeon oder Schlachtzug oder ein Ziel, das lange genug lebt). Fallenplatzierung, Irreführung, Totstellen und Defensivfähigkeiten bleiben Ihnen überlassen; die Erinnerungen an Freudentaumel und Abschreckung sind standardmäßig deaktiviert."
L["rm.mop.hunter.marksmanship.Name"] = "Empfohlen"
L["rm.mop.hunter.marksmanship.Description"] = "Automatisch gewählt in der Spezialisierung Treffsicherheit. Wirkt Gezielter Schuss vor, dann: Zuverlässiger Schuss paarweise, um Beständiger Fokus aufrechtzuerhalten (ab Stufe 63), Schimärenschuss, Schlangengift auf Zielen, die lange genug leben, Gezielter Schuss, wann immer Feuer! ihn sofort wirkbar macht, Tödlicher Schuss, Ihre Talente und ein voll gewirkter Gezielter Schuss, solange das Ziel über 80 % Gesundheit hat, während Schnellfeuer oder Kampfrausch, bei 85 Fokus oder wenn Schimärenschuss nur noch wenige Sekunden entfernt ist. Arkaner Schuss nur in Bewegung; sonst Zuverlässiger Schuss. Vier oder mehr Gegner: Schimärenschuss, sofortiger Gezielter Schuss, Mehrfachschuss, Tödlicher Schuss, Sprengfalle. Dieselben Erinnerungen wie die anderen integrierten Jägerrotationen. Wenn Sie überschüssigen Fokus lieber für Arkaner Schuss ausgeben, verwenden Sie die Variante mit Arkanem Schuss."
L["rm.mop.hunter.marksmanship.icyveins.Name"] = "Fokusabbau mit Arkanem Schuss (Icy Veins)"
L["rm.mop.hunter.marksmanship.icyveins.Description"] = "Eine Alternative zur integrierten Treffsicherheit-Rotation, wie Icy Veins, Method, wowtbc.gg und Hekili sie spielen: Gezielter Schuss wird nur über 80 % Gesundheit des Ziels oder während Schnellfeuer oder Kampfrausch voll gewirkt, und überschüssiger Fokus geht stattdessen bei 60 in Arkaner Schuss. Beständiger Fokus wird unter 4 Sekunden erneuert; gegen vier oder mehr Gegner kommt Mehrfachschuss zuerst. Standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die integrierte Treffsicherheit-Rotation, oder erhöhen Sie ihre Priorität."
L["rm.mop.hunter.survival.Name"] = "Empfohlen"
L["rm.mop.hunter.survival.Description"] = "Automatisch gewählt in der Spezialisierung Überleben. Eröffnet mit Mal des Jägers, Schwarzem Pfeil und Explosivschuss, dann: Explosivschuss bei Abklingzeit-Ende und bei jedem Sichern und Laden, Tödlicher Schuss, Schwarzer Pfeil auf Zielen, die lange genug leben, Ihre Talente, Schlangengift durch Kobraschuss aufrechterhalten, Arkaner Schuss bei 75 Fokus, mit Jagdfieber oder bei 55, wenn Schwarzer Pfeil nicht bald bereit ist, dann Kobraschuss (Zuverlässiger Schuss vor Stufe 81). Zwei oder mehr Gegner: Mehrfachschuss zuerst bei Sichern und Laden mit vollem Fokus, Explosivschuss auf bis zu fünf Ziele, Tödlicher Schuss, Schwarzer Pfeil, Sprengfalle ab drei Gegnern, Mehrfachschuss zum Fokusabbau. Dieselben Erinnerungen wie die anderen integrierten Jägerrotationen; Fallen für Procs von Sichern und Laden bleiben Ihnen überlassen."
L["rm.mop.hunter.unspecialized.Name"] = "Vor einer Spezialisierung"
L["rm.mop.hunter.unspecialized.Description"] = "Für Stufe 1 bis 9 und jeden Jäger, der keine Spezialisierung gewählt hat; die integrierten Rotationen für Tierherrschaft, Treffsicherheit und Überleben übernehmen, sobald Sie eine Spezialisierung wählen. Zieht mit Mal des Jägers und Arkanem Schuss, dann Schlangengift auf Zielen, die lange genug leben, Mehrfachschuss gegen drei oder mehr Gegner, Arkaner Schuss, Zuverlässiger Schuss und Automatischer Schuss. Erinnert Sie daran, Ihren Begleiter zu rufen, wiederzubeleben und zu heilen und Aspekt des Falken aufrechtzuerhalten."
L["rm.retail.hunter.beastmastery.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.hunter.beastmastery.Description"] = "Empfohlen für Tierherrschaft. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt (er ruft Ihren Begleiter selbst); sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Blutvergießen und Ihre Volksfähigkeit im Kampf, Gegenschuss bei einem unterbrechbaren Zauber und Überleben des Stärkeren, wann immer es im Kampf bereit ist. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet die Unterbrechung nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz Ihrer Defensivfähigkeiten (einschließlich Freudentaumel und Aspekt der Schildkröte) Ihnen überlassen. Schmuckstücke, Irreführung und die Pflege des Begleiters bleiben Ihnen überlassen."
L["rm.retail.hunter.beastmastery.guide.Name"] = "Referenz (SimulationCraft und Icy Veins)"
L["rm.retail.hunter.beastmastery.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die optimierte Priorität für Tierherrschaft. Aufladungen, Abklingzeiten und Procs sind im Kampf in Midnight für Addons verborgen, daher kann sie dort nicht laufen; lesen Sie sie, oder duplizieren Sie sie, um damit zu experimentieren. Fokus ist auf Retail verborgen. Ruft Ihren Begleiter und markiert das Ziel vor dem Pull. Stachelpfeil kurz vor Zorn des Wildtiers oder bevor seine Aufladungen das Maximum erreichen; Zorn des Wildtiers; Tötungsbefehl bei Heulen des Rudelführers oder Verbündetem der Natur oder frei, solange Zorn des Wildtiers noch lange nicht bereit ist; Kobraschuss bei Kobrazahn; Kobraschuss; Stachelpfeil, wenn Kobraschuss nicht bezahlbar ist. Dunkler Waldläufer: Schwarzer Pfeil während Vernichtendem Feuer und Klagender Pfeil, wenn es endet. Drei oder mehr Gegner (zwei mit dem Talent Raubtierhiebe): Wildes Hauen, um Raubtierhiebe zu starten, dann Tötungsbefehl, Stachelpfeil und Kobraschuss, solange sie anhalten. Erinnerungen: Blutvergießen, dazu die Erinnerungen an Hilfsfähigkeiten aus der integrierten Kampfassistent-Rotation."
L["rm.retail.hunter.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.hunter.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Jägers meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Jäger-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.hunter.marksmanship.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.hunter.marksmanship.Description"] = "Empfohlen für Treffsicherheit. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Volltreffer und Ihre Volksfähigkeit im Kampf, Gegenschuss bei einem unterbrechbaren Zauber und Überleben des Stärkeren, wann immer es im Kampf bereit ist. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet die Unterbrechung nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz Ihrer Defensivfähigkeiten (einschließlich Freudentaumel und Aspekt der Schildkröte) Ihnen überlassen."
L["rm.retail.hunter.marksmanship.guide.Name"] = "Referenz (SimulationCraft und Icy Veins)"
L["rm.retail.hunter.marksmanship.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die optimierte Priorität für Treffsicherheit, die Präzise Schüsse vor dem nächsten Gezielten Schuss verbraucht. Procs und Aufladungen sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; Fokus ist auf Retail verborgen, daher fehlt der Mehrfachschuss ab 70 Fokus gegen Gruppen. Markiert das Ziel und eröffnet mit Gezieltem Schuss. Schildwache: Explosivschuss, Salve, Volltreffer, Mondscheinchakram, bevor sein Zeitfenster endet, Gezielter Schuss während Volltreffer ohne Präzise Schüsse, Schnellfeuer, Tödlicher Schuss, Mehrfachschuss (zwei Gegner mit Aspekt der Hydra) oder Arkaner Schuss bei Präzisen Schüssen, Gezielter Schuss, Mondscheinchakram, Zuverlässiger Schuss. Dunkler Waldläufer: zuerst Schwarzer Pfeil bei Präzisen Schüssen, kein Explosivschuss während Sichern und Laden, Gezielter Schuss, bevor seine Aufladungen das Maximum erreichen, Klagender Pfeil. Drei oder mehr Gegner mit Gekonnten Schüssen: Explosivschuss, Salve, Mehrfachschuss, um Gekonnte Schüsse auszulösen, Volltreffer, dann Schnellfeuer und Gezielter Schuss, solange es anhält. Ob Sie Volltreffer für 30 Stapel Ins Schwarze oder für ein unmarkiertes Ziel einsetzen, bleibt Ihnen überlassen."
L["rm.retail.hunter.survival.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.hunter.survival.Description"] = "Empfohlen für Überleben. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt (er ruft Ihren Begleiter selbst); sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Ausschalten und Ihre Volksfähigkeit im Kampf, Maulkorb bei einem unterbrechbaren Zauber und Überleben des Stärkeren, wann immer es im Kampf bereit ist. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet die Unterbrechung nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz Ihrer Defensivfähigkeiten (einschließlich Freudentaumel und Aspekt der Schildkröte) Ihnen überlassen."
L["rm.retail.hunter.survival.guide.Name"] = "Referenz (SimulationCraft)"
L["rm.retail.hunter.survival.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität von SimulationCraft für Überleben, in der Tötungsbefehl Speerspitze aufbaut und Ausschalten, Schrotbüchse, Lauffeuerbombe und Raptorstoß sie verbrauchen. Speerspitze und Aufladungen sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen. Ruft Ihren Begleiter, markiert das Ziel und eröffnet mit Lauffeuerbombe. Schildwache: Tötungsbefehl ohne Speerspitze, Schrotbüchse, Lauffeuerbombe bei Mal der Schildwache, Tötungsbefehl vor einem bereiten Ausschalten, Ausschalten, Mondscheinchakram, Raptorstoß, dann Tötungsbefehl, Lauffeuerbombe und Ausschalten. Rudelführer: Tötungsbefehl bei Heulen des Rudelführers, dann Ausschalten, Lauffeuerbombe, Schrotbüchse und Raptorstoß mit Speerspitze. Drei oder mehr Gegner: Schrotbüchse und Lauffeuerbombe vor Ausschalten, Raptorhieb. Erinnerungen: Aspekt des Adlers außerhalb des Nahkampfs und die Erinnerungen an Hilfsfähigkeiten."
L["rm.sod.hunter.melee.Name"] = "Nahkampf (SoD)"
L["rm.sod.hunter.melee.Description"] = "Gewählt auf einem Realm der Saison der Entdeckungen, sobald Sie Flankenangriff, Flügeldrachenstoß oder Zerlegen graviert haben und weder Schimärenschuss noch Explosivschuss. Hält den Stärkungszauber von Flankenangriff aufrecht, Mungobiss bei vier Stapeln Raptorenfuror, Flügeldrachenstoß bei Gewiefte Stöße, Raptorstoß bei jedem Zurücksetzen, dann Mungobiss, Flügeldrachenstoß, Flankenangriff und Zerlegen; Feuerbrandfalle und Zurechtstutzen nur in leeren Momenten. Zerlegen und Sprengfalle gegen drei oder mehr Gegner; Schlangenbiss und Schüsse, solange Sie das Ziel nicht erreichen. Erinnerungen: Aspekt des Gerfalken (vor Stufe 60 Falke), Viper unter 5 % Mana, Begleiterpflege (keine mit eingravierter Rune Einsamer Wolf), Schnellfeuer und Volksfähigkeiten, sobald Flankenangriff gestapelt ist, Zorn des Wildtiers. Positionierung und Begleiterbefehle bleiben Ihnen überlassen."
L["rm.sod.hunter.ranged.Name"] = "Fernkampf (SoD)"
L["rm.sod.hunter.ranged.Description"] = "Jeder Fernkampfjäger auf einem Realm der Saison der Entdeckungen, Stufe 1 bis 60; Runen werden genutzt, sobald sie graviert sind. Schlangenbiss immer aktiv und durch Schimärenschuss erneuert. Mit der Beinrune Tödlicher Schuss: Mehrfachschuss bei vier Stapeln Gekonnte Schüsse, Tödlicher Schuss während Schnellfeuer und auf Ziele in der Hinrichtungsphase, Schimärenschuss, dann Sprengfalle und Arkaner Schuss, während Mehrfachschuss abklingt. Ohne sie: Schimärenschuss, Gezielter Schuss bei zwei Stapeln Scharfschützentraining (ohne diese Rune direkt nach einem Automatischen Schuss), Fallen kurz bevor Schimärenschuss bereit ist (Frostfalle nur, um Sichern und Laden auszulösen), Explosivschuss, Zuverlässiger Schuss, Mehrfachschuss, Arkaner Schuss. Nahkampftasten, wenn ein Gegner zu nah ist, Spontanzauber in Bewegung, Fallen, Mehrfachschuss und Salve gegen drei oder mehr Gegner. Erinnerungen: Falke, Viper unter 10 % Mana, Löwenherz, Aura des Volltreffers, Begleiterpflege (keine mit eingravierter Rune Einsamer Wolf), Fokussiertes Feuer bei fünf Stapeln Raserei, Schnellfeuer, Volksfähigkeiten und Zorn des Wildtiers gegen Elitegegner und in Instanzen. Mit eingravierter Rune Sichern und Laden eine Frostfalle vor dem Pull. Nahkampf-Weaving und Positionierung bleiben Ihnen überlassen."
L["rm.tbc.hunter.ranged.simulator.Name"] = "Fernkampf-DPS (Simulation)"
L["rm.tbc.hunter.ranged.simulator.Description"] = "Stufen 1–70, jede Spezialisierung. Zieht mit Mal des Jägers, Gezieltem Schuss und Automatischem Schuss, hält den Automatischen Schuss am Laufen und nutzt Nahkampfangriffe, wenn ein Ziel Sie erreicht. Vor Zuverlässigem Schuss hält sie Ihren Schlangenbiss aufrecht und gibt Mana für Gezielten, Mehrfach- und Arkanen Schuss nur aus, solange Sie reichlich haben. Ab Stufe 62: Mehrfachschuss, sobald bereit, Zuverlässiger Schuss direkt nach jedem Automatischen Schuss, Arkaner Schuss zum Füllen der Lücke, Schlangenbiss beim Solospiel. Wenn drei oder mehr Gegner gegen Sie kämpfen, Mehrfachschuss, sobald er bereit ist. Erinnert an Aspekte (Viper bei knappem Mana, Falke wieder bei halbem Mana), Begleiterpflege, Fass!, große Abklingzeiten gegen Elitegegner und Bosse sowie Unterdrückenden Schuss. Begleiterbefehle, Irreführung, Fallen, Salve, Nahkampf-Weaving und Totstellen bleiben Ihnen überlassen."
L["rm.tbc.hunter.ranged.wowhead.Name"] = "Fernkampf-DPS (Wowhead)"
L["rm.tbc.hunter.ranged.wowhead.Description"] = "Stufen 1–70, jede Spezialisierung, nach den Schlachtzugsempfehlungen von Wowhead. Derselbe Pull, Nahkampf, dieselben Leveling-Schüsse, Mehrfachschuss gegen mehrere Ziele und Erinnerungen wie die Simulation-Version, aber sobald Zuverlässiger Schuss erlernt ist, bietet sie nach jedem Automatischen Schuss nur Mehrfachschuss und Zuverlässigen Schuss an: kein Arkaner Schuss als Füller (außer in Bewegung), kein Schlangenbiss und keine Erinnerung an Aspekt der Viper. Begleiterbefehle, Irreführung, Fallen, Salve, Nahkampf-Weaving und Totstellen bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Fernkampfrotation nach Simulation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
